ALTER TABLE `month_signoffs` ADD `calendar_id` integer;--> statement-breakpoint
-- A sign-off may get its calendar once (rows from before this migration or from rt import-v1); never another.
DROP TRIGGER IF EXISTS trg_signoffs_immutable;
--> statement-breakpoint
CREATE TRIGGER trg_signoffs_immutable BEFORE UPDATE ON month_signoffs FOR EACH ROW WHEN (OLD.calendar_id IS NOT NULL AND NEW.calendar_id IS NOT OLD.calendar_id) OR (NOT (OLD.calendar_id IS NULL AND NEW.calendar_id IS NOT NULL AND NEW.reopened_at IS OLD.reopened_at AND NEW.reopened_by_id IS OLD.reopened_by_id AND NEW.reopen_reason IS OLD.reopen_reason AND NEW.note IS OLD.note AND NEW.user_id IS OLD.user_id AND NEW.month IS OLD.month AND NEW.period_start_date IS OLD.period_start_date AND NEW.period_end_date IS OLD.period_end_date AND NEW.period_start_utc IS OLD.period_start_utc AND NEW.period_end_utc IS OLD.period_end_utc AND NEW.signed_by_id IS OLD.signed_by_id AND NEW.signed_at IS OLD.signed_at AND NEW.snapshot IS OLD.snapshot AND NEW.digest IS OLD.digest AND NEW.seal IS OLD.seal AND NEW.prev_seal IS OLD.prev_seal AND NEW.seal_version IS OLD.seal_version) AND (OLD.reopened_at IS NOT NULL OR NEW.reopened_at IS NULL OR NEW.user_id IS NOT OLD.user_id OR NEW.month IS NOT OLD.month OR NEW.period_start_date IS NOT OLD.period_start_date OR NEW.period_end_date IS NOT OLD.period_end_date OR NEW.period_start_utc IS NOT OLD.period_start_utc OR NEW.period_end_utc IS NOT OLD.period_end_utc OR NEW.signed_by_id IS NOT OLD.signed_by_id OR NEW.signed_at IS NOT OLD.signed_at OR NEW.snapshot IS NOT OLD.snapshot OR NEW.digest IS NOT OLD.digest OR NEW.seal IS NOT OLD.seal OR NEW.prev_seal IS NOT OLD.prev_seal OR NEW.seal_version IS NOT OLD.seal_version)) BEGIN SELECT RAISE(ABORT, 'resorixtrack: sign-offs are immutable'); END;
--> statement-breakpoint
-- existing sign-offs keep the calendar that applies today (own, else the team's, else the company default)
UPDATE month_signoffs SET calendar_id = COALESCE((SELECT c.id FROM users u JOIN holiday_calendars c ON c.id = u.holiday_calendar_id WHERE u.id = month_signoffs.user_id), (SELECT c.id FROM users u JOIN teams t ON t.id = u.team_id JOIN holiday_calendars c ON c.id = t.holiday_calendar_id WHERE u.id = month_signoffs.user_id), (SELECT id FROM holiday_calendars WHERE is_default = 1 ORDER BY id LIMIT 1)) WHERE calendar_id IS NULL;
